def _sfield(s, key):
    marker = '"' + key + '"'
    i = s.find(marker)
    if i < 0:
        return None
    j = s.find(":", i + len(marker))
    if j < 0:
        return None
    k = j + 1
    while k < len(s) and s[k] == " ":
        k = k + 1
    if k >= len(s):
        return None
    if s[k] == '"':
        k = k + 1
        buf = ""
        while k < len(s):
            ch = s[k]
            if ch == "\\" and k + 1 < len(s):
                buf = buf + s[k + 1]
                k = k + 2
                continue
            if ch == '"':
                break
            buf = buf + ch
            k = k + 1
        return buf
    # bare literal (number / true / false / null)
    buf = ""
    while k < len(s) and s[k] not in ",}":
        buf = buf + s[k]
        k = k + 1
    return buf.strip()
